//! 💠️ Literal Lowpoly fields retain native binary32 words, paint octets and independent mesh handles.
use super::LowpolySnapshot;
use crate::{LowpolyObject,LowpolyTransform,LowpolyPaintLayer};
use store::{ArtifactSqliteSnapshot,sqlite_snapshot::{SqliteDatabase,SqliteRow,SqliteSnapshotControl,SqliteSnapshotPhase,SnapshotEncoding,validate_sqlite_database_schema,artifact::{Projection,Cell,FloatColumn,FloatRow,insert_key_ieee754,insert_ieee754,NativeEncodingBound}}};
use std::collections::BTreeMap;
const TRANSFORM:&[FloatColumn]=&[FloatColumn::Binary32(1),FloatColumn::Binary32(2),FloatColumn::Binary32(3),FloatColumn::Binary32(4),FloatColumn::Binary32(5),FloatColumn::Binary32(6),FloatColumn::Binary32(7),FloatColumn::Binary32(8),FloatColumn::Binary32(9)];
const OPACITY:&[FloatColumn]=&[FloatColumn::Binary32(5)];
fn plus(value:&mut usize,additional:usize)->Result<(),String>{*value=value.checked_add(additional).ok_or("Lowpoly admission overflow")?;Ok(())}
fn rows(snapshot:&LowpolySnapshot,control:&mut SqliteSnapshotControl<'_>)->Result<usize,String>{
 let mut rows=1usize;let mut bytes=snapshot.schema.len();control.checkpoint(SqliteSnapshotPhase::ProjectSnapshot,0,snapshot.objects.len())?;
 for(index,object)in snapshot.objects.iter().enumerate(){plus(&mut rows,2)?;for value in[&object.id,&object.name,&object.mesh_content]{plus(&mut bytes,value.len())?;}
 if let Some(child)=&object.mesh{plus(&mut rows,1)?;for value in[&child.child_id,&child.target.artifact_id,&child.target.dialect.artifact_kind,&child.target.dialect.standard,&child.target.dialect.subset]{plus(&mut bytes,value.len())?;}}
 control.checkpoint(SqliteSnapshotPhase::ProjectSnapshot,0,object.paint_layers.len())?;for(index,layer)in object.paint_layers.iter().enumerate(){plus(&mut rows,1)?;plus(&mut rows,layer.pixels.len())?;plus(&mut bytes,layer.name.len())?;plus(&mut bytes,layer.blend_mode.len())?;control.check_rows(rows)?;if(index+1)%256==0{control.checkpoint(SqliteSnapshotPhase::ProjectSnapshot,index+1,object.paint_layers.len())?;}}control.checkpoint(SqliteSnapshotPhase::ProjectSnapshot,object.paint_layers.len(),object.paint_layers.len())?;
 control.check_rows(rows)?;control.check_value_bytes(bytes.checked_add(rows.checked_mul(192).ok_or("Lowpoly lookup admission overflow")?).ok_or("Lowpoly value admission overflow")?)?;if(index+1)%256==0{control.checkpoint(SqliteSnapshotPhase::ProjectSnapshot,index+1,snapshot.objects.len())?;}
 }control.check_rows(rows)?;control.check_value_bytes(bytes.checked_add(rows.checked_mul(192).ok_or("Lowpoly lookup admission overflow")?).ok_or("Lowpoly value admission overflow")?)?;Ok(rows)
}
fn native_rows(record:&dsl::RecordValue,control:&mut dsl::NativeDecodeControl<'_>,maximum:usize)->Result<(),String>{
 fn list(record:&dsl::RecordValue,id:u16)->Result<&[dsl::FieldValue],String>{match record.get(id){Some(dsl::FieldValue::List(values))=>Ok(values),_=>Err("Lowpoly native ordered occurrence field differs".into())}}
 fn owned(value:&dsl::FieldValue)->Result<&dsl::RecordValue,String>{match value{dsl::FieldValue::Record(value)=>Ok(value),_=>Err("Lowpoly native typed object differs".into())}}
 let objects=list(record,1)?;let mut count=1usize;control.begin_stage(objects.len())?;
 for value in objects{control.step()?;let object=owned(value)?;plus(&mut count,2)?;match object.get(4){None|Some(dsl::FieldValue::Absent)=>{},Some(dsl::FieldValue::Record(_))=>plus(&mut count,1)?,_=>return Err("Lowpoly native optional mesh field differs".into())}
 let layers=list(object,5)?;control.scoped_stage(|control|->Result<(),String>{control.begin_stage(layers.len())?;for value in layers{control.step()?;let layer=owned(value)?;let bytes=match layer.get(4){Some(dsl::FieldValue::Bytes64(bytes))=>bytes.len(),_=>return Err("Lowpoly native intrinsic pixel bytes differ".into())};plus(&mut count,1)?;plus(&mut count,bytes)?;if count>maximum{return Err("Lowpoly native semantic row limit".into())}}Ok(())})?;if count>maximum{return Err("Lowpoly native semantic row limit".into())}
 }if count>maximum{return Err("Lowpoly native semantic row limit".into())}control.checkpoint()
}
fn keyed<'a>(rows:&'a[SqliteRow],width:usize,control:&mut dsl::NativeDecodeControl<'_>)->Result<BTreeMap<i64,&'a SqliteRow>,String>{control.begin_stage(rows.len())?;let mut result=BTreeMap::new();for row in rows{control.step()?;if row.values.len()!=width||row.integer(0)?!=row.rowid||result.insert(row.rowid,row).is_some(){return Err("Lowpoly identity or row width differs".into())}}Ok(result)}
fn boolean(row:&SqliteRow,index:usize)->Result<bool,String>{match row.integer(index)?{0=>Ok(false),1=>Ok(true),_=>Err("Lowpoly boolean exceeds its domain".into())}}
fn grouped<'a>(rows:&'a[SqliteRow],column:usize,parents:&BTreeMap<i64,&SqliteRow>,control:&mut dsl::NativeDecodeControl<'_>)->Result<BTreeMap<i64,Vec<&'a SqliteRow>>,String>{control.begin_stage(rows.len())?;let mut result=BTreeMap::new();for row in rows{control.step()?;let owner=row.integer(column)?;if !parents.contains_key(&owner){return Err("Lowpoly occurrence has an unknown owner".into())}result.entry(owner).or_insert_with(Vec::new).push(row);}Ok(result)}
fn ordered<'a>(rows:Vec<&'a SqliteRow>,column:usize,control:&mut dsl::NativeDecodeControl<'_>)->Result<Vec<&'a SqliteRow>,String>{control.begin_stage(rows.len())?;let mut result=control.allocate_vec::<Option<&SqliteRow>>(rows.len())?;result.resize(rows.len(),None);for row in rows{control.step()?;let ordinal=usize::try_from(row.integer(column)?).map_err(|_|"Lowpoly ordinal exceeds native width")?;if ordinal>=result.len()||result[ordinal].replace(row).is_some(){return Err("Lowpoly ordinals are not contiguous".into())}}let mut values=control.allocate_vec(result.len())?;for row in result{values.push(row.ok_or("Lowpoly missing ordinal")?);}Ok(values)}
impl ArtifactSqliteSnapshot for LowpolySnapshot{
 const SQLITE_SCHEMA:&'static str=include_str!("🗄️.sql");
 fn encode_sqlite_snapshot_native(&self,encoding:SnapshotEncoding,control:&mut SqliteSnapshotControl<'_>)->Result<store::io_schema::IoPayload,String>{
  control.checkpoint(SqliteSnapshotPhase::EncodeNative,0,self.objects.len())?;let mut count=1usize;control.check_rows(count)?;for(index,object)in self.objects.iter().enumerate(){plus(&mut count,2)?;if object.mesh.is_some(){plus(&mut count,1)?;}control.check_rows(count)?;control.checkpoint(SqliteSnapshotPhase::EncodeNative,0,object.paint_layers.len())?;for(index,layer)in object.paint_layers.iter().enumerate(){plus(&mut count,1)?;plus(&mut count,layer.pixels.len())?;control.check_rows(count)?;if(index+1)%256==0{control.checkpoint(SqliteSnapshotPhase::EncodeNative,index+1,object.paint_layers.len())?;}}control.checkpoint(SqliteSnapshotPhase::EncodeNative,object.paint_layers.len(),object.paint_layers.len())?;if(index+1)%256==0{control.checkpoint(SqliteSnapshotPhase::EncodeNative,index+1,self.objects.len())?;}}control.checkpoint(SqliteSnapshotPhase::EncodeNative,self.objects.len(),self.objects.len())?;
  store::encode_sqlite_snapshot_record_native(encoding,"lowpoly.lowpoly",Self::__dsl_spec_producer(),|native|self.__dsl_to_record_controlled(native),control)
 }
 fn decode_sqlite_snapshot_native(payload:&store::io_schema::IoPayload,control:&mut SqliteSnapshotControl<'_>)->Result<Self,String>{let maximum=control.limits().max_rows;store::decode_sqlite_snapshot_record_native(payload,"lowpoly.lowpoly",Self::__dsl_spec_producer(),|record,native|{native.scoped_stage(|native|native_rows(record,native,maximum)).map_err(dsl::__rt::field_error)?;Self::__dsl_from_record_controlled(record,native)},control)}
 fn preflight_sqlite_snapshot_encoding(&self,_encoding:SnapshotEncoding,control:&mut SqliteSnapshotControl<'_>)->Result<(),String>{let mut bound=NativeEncodingBound::new(control)?;bound.add(4096)?;bound.repeated(self.schema.len(),12)?;for object in&self.objects{bound.add(4096)?;for value in[&object.id,&object.name,&object.mesh_content]{bound.repeated(value.len(),12)?;}if let Some(child)=&object.mesh{bound.add(2048)?;for value in[&child.child_id,&child.target.artifact_id,&child.target.dialect.artifact_kind,&child.target.dialect.standard,&child.target.dialect.subset]{bound.repeated(value.len(),12)?;}}for layer in&object.paint_layers{bound.add(2048)?;bound.repeated(layer.name.len(),12)?;bound.repeated(layer.blend_mode.len(),12)?;bound.repeated(layer.pixels.len(),8)?;}}bound.finish()}
 fn to_sqlite_database(&self,control:&mut SqliteSnapshotControl<'_>)->Result<SqliteDatabase,String>{
 let total=rows(self,control)?;let mut p=Projection::new(Self::SQLITE_SCHEMA,control)?;p.insert_key("lowpoly_document",1,&[Cell::Text(&self.schema)])?;let mut layer_id=0i64;
 for(index,object)in self.objects.iter().enumerate(){let ordinal=i64::try_from(index).map_err(|_|"Lowpoly occurrence ordinal exceeds SQLite integer")?;let id=ordinal.checked_add(1).ok_or("Lowpoly identity overflow")?;p.insert_key("lowpoly_object",id,&[Cell::Integer(1),Cell::Integer(ordinal),Cell::Text(&object.id),Cell::Text(&object.name),Cell::Integer(i64::from(object.smooth_shading)),Cell::Text(&object.mesh_content)])?;
 let t=&object.transform;insert_key_ieee754(&mut p,"lowpoly_transform",id,&[Cell::Float32(t.position[0]),Cell::Float32(t.position[1]),Cell::Float32(t.position[2]),Cell::Float32(t.rotation[0]),Cell::Float32(t.rotation[1]),Cell::Float32(t.rotation[2]),Cell::Float32(t.scale[0]),Cell::Float32(t.scale[1]),Cell::Float32(t.scale[2])],TRANSFORM)?;
 if let Some(child)=&object.mesh{p.insert_key("lowpoly_mesh_child",id,&[Cell::Text(&child.child_id),Cell::Text(&child.target.artifact_id),Cell::Text(&child.target.dialect.artifact_kind),Cell::Text(&child.target.dialect.standard),Cell::Text(&child.target.dialect.subset)])?;}
 for(index,layer)in object.paint_layers.iter().enumerate(){layer_id=layer_id.checked_add(1).ok_or("Lowpoly layer identity overflow")?;insert_ieee754(&mut p,"lowpoly_paint_layer",&[Cell::Integer(id),Cell::Integer(i64::try_from(index).map_err(|_|"Lowpoly layer ordinal exceeds SQLite integer")?),Cell::Text(&layer.name),Cell::Integer(i64::from(layer.visible)),Cell::Float32(layer.opacity),Cell::Text(&layer.blend_mode)],OPACITY)?;
 for(index,byte)in layer.pixels.iter().enumerate(){p.insert("lowpoly_paint_octet",&[Cell::Integer(layer_id),Cell::Integer(i64::try_from(index).map_err(|_|"Lowpoly pixel ordinal exceeds SQLite integer")?),Cell::Integer(i64::from(*byte))])?;if(index+1)%256==0{p.checkpoint_total(total)?;}}}
 }p.checkpoint_total(total)?;p.finish()
 }
 fn from_sqlite_database(database:&SqliteDatabase,control:&mut SqliteSnapshotControl<'_>)->Result<Self,String>{
 control.check_database(database,SqliteSnapshotPhase::ReconstructSnapshot)?;validate_sqlite_database_schema(database,Self::SQLITE_SCHEMA,control.limits()).map_err(|e|e.to_string())?;let total=database.tables.iter().try_fold(0usize,|n,t|n.checked_add(t.rows.len()).ok_or("Lowpoly row count overflow"))?;control.check_value_bytes(total.checked_mul(192).ok_or("Lowpoly lookup admission overflow")?)?;
 let maximum=control.limits().max_value_bytes;let mut progress=|state:protocol::native_decoding::NativeDecodeProgress|control.checkpoint(SqliteSnapshotPhase::ReconstructSnapshot,state.completed,state.total).is_ok();let mut native=dsl::NativeDecodeControl::new(maximum,&mut progress);native.charge(total.checked_mul(192).ok_or("Lowpoly lookup admission overflow")?)?;native.begin_stage(total)?;
 for table in&database.tables{for _ in&table.rows{native.step()?;}}
 let documents=keyed(&database.table("lowpoly_document")?.rows,2,&mut native)?;let objects=keyed(&database.table("lowpoly_object")?.rows,7,&mut native)?;let mut transforms=keyed(&database.table("lowpoly_transform")?.rows,28,&mut native)?;let mut children=keyed(&database.table("lowpoly_mesh_child")?.rows,6,&mut native)?;let layers=keyed(&database.table("lowpoly_paint_layer")?.rows,9,&mut native)?;let octets=database.table("lowpoly_paint_octet")?;keyed(&octets.rows,4,&mut native)?;
 if documents.len()!=1||transforms.len()!=objects.len(){return Err("Lowpoly document or transform cardinality differs".into())}let document=*documents.values().next().ok_or("Lowpoly document missing")?;for object in objects.values(){if object.integer(1)?!=document.rowid{return Err("Lowpoly object document differs".into())}}
 let mut layer_groups=grouped(&database.table("lowpoly_paint_layer")?.rows,1,&objects,&mut native)?;let mut octet_groups=grouped(&octets.rows,1,&layers,&mut native)?;let mut object_rows=native.allocate_vec(objects.len())?;native.begin_stage(objects.len())?;for row in objects.values(){native.step()?;object_rows.push(*row);}let ordered_objects=ordered(object_rows,2,&mut native)?;let mut result=LowpolySnapshot{schema:native.copy_text(document.text(1)?)?,objects:native.allocate_vec(ordered_objects.len())?};
 for row in ordered_objects{native.checkpoint()?;let transform=FloatRow::new(transforms.remove(&row.rowid).ok_or("Lowpoly transform owner missing")?,TRANSFORM)?;let transform=LowpolyTransform{position:[transform.binary32(1)?,transform.binary32(2)?,transform.binary32(3)?],rotation:[transform.binary32(4)?,transform.binary32(5)?,transform.binary32(6)?],scale:[transform.binary32(7)?,transform.binary32(8)?,transform.binary32(9)?]};
 let mesh=if let Some(child)=children.remove(&row.rowid){Some(store::ArtifactChild::new(native.copy_text(child.text(1)?)?,store::io_schema::ArtifactRef{artifact_id:native.copy_text(child.text(2)?)?,dialect:store::io_schema::ArtifactDialect{artifact_kind:native.copy_text(child.text(3)?)?,standard:native.copy_text(child.text(4)?)?,subset:native.copy_text(child.text(5)?)?}}))}else{None};
 let rows=ordered(layer_groups.remove(&row.rowid).unwrap_or_default(),2,&mut native)?;let mut paint_layers=native.allocate_vec(rows.len())?;
 for layer in rows{native.checkpoint()?;let rows=ordered(octet_groups.remove(&layer.rowid).unwrap_or_default(),2,&mut native)?;let mut pixels=native.allocate_vec(rows.len())?;native.begin_stage(rows.len())?;for row in rows{native.step()?;pixels.push(u8::try_from(row.integer(3)?).map_err(|_|"Lowpoly paint sample exceeds octet")?);}paint_layers.push(LowpolyPaintLayer{name:native.copy_text(layer.text(3)?)?,visible:boolean(layer,4)?,opacity:FloatRow::new(layer,OPACITY)?.binary32(5)?,blend_mode:native.copy_text(layer.text(6)?)?,pixels});}
 result.objects.push(LowpolyObject{id:native.copy_text(row.text(3)?)?,name:native.copy_text(row.text(4)?)?,transform,smooth_shading:boolean(row,5)?,mesh,paint_layers,mesh_content:native.copy_text(row.text(6)?)?});
 }if !transforms.is_empty()||!children.is_empty()||!layer_groups.is_empty()||!octet_groups.is_empty(){return Err("Lowpoly unowned semantic entities".into())}native.checkpoint()?;Ok(result)
 }
 fn validate_sqlite_snapshot_subset(&self,dialect:&store::io_schema::ArtifactDialect,database:&SqliteDatabase,control:&mut SqliteSnapshotControl<'_>)->store::io_schema::IoResult<()>{control.checkpoint(SqliteSnapshotPhase::ProjectSnapshot,0,0)?;if dialect.artifact_kind!="s.lowpoly.lowpoly"||dialect.standard!="1"||dialect.subset!="*"{return Err(String::from("Lowpoly does not own this semantic subset").into())}let candidate=Self::from_sqlite_database(database,control)?;if candidate.to_sqlite_database(control)?!=self.to_sqlite_database(control)?{return Err(String::from("Lowpoly logical snapshot state differs").into())}Ok(store::io_schema::IoOutcome::clean(()))}
}
